    private static final String[] SPECIES={"Cow","Buffalo","Goat","Sheep","Rabbit","Poultry","Dog","Other"}, STATUS={"Healthy","Sick","Recovering","Unknown"}, TYPES={"health","vaccine","deworm","breeding","production","feed","finance"};
