    int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}
    String t(String en,String hn){return hi?hn:en;}
    String today(){return LocalDate.now().toString();}
    int idx(String[] a,String k){for(int i=0;i<a.length;i++)if(a[i].equals(k))return i;return -1;}
    String typeName(String k){int i=idx(TYPES,k);return i<0?k:t(TYPE_EN[i],TYPE_HI[i]);}
    String speciesName(String k){int i=idx(SPECIES,k);return i<0?k:t(k,new String[]{"गाय","भैंस","बकरी","भेड़","खरगोश","मुर्गी","कुत्ता","अन्य"}[i]);}
    String statusName(String k){int i=idx(STATUS,k);return i<0?k:t(k,new String[]{"स्वस्थ","बीमार","ठीक हो रहा","अज्ञात"}[i]);}
    String n(double d){return new java.text.DecimalFormat("0.##").format(d);}
    String cash(double d){return "₹"+java.text.NumberFormat.getNumberInstance(new Locale("en","IN")).format(d);}
    String val(JSONObject o,String k){String v=str(o,k);return v.isEmpty()?"—":v;}
    ArrayList<JSONObject> animals(){return rows(data.optJSONArray("animals"));}
    ArrayList<JSONObject> records(){return rows(data.optJSONArray("records"));}
    JSONObject animal(String id){for(JSONObject a:animals())if(str(a,"id").equals(id))return a;return null;}
    JSONObject record(String id){for(JSONObject a:records())if(str(a,"id").equals(id))return a;return null;}
    ArrayList<JSONObject> history(String id){ArrayList<JSONObject> out=new ArrayList<>();for(JSONObject r:records())if(str(r,"animal").equals(id))out.add(r);out.sort((a,b)->str(b,"date").compareTo(str(a,"date")));return out;}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    GradientDrawable bordered(int color,int radius,int stroke){GradientDrawable d=bg(color,radius);d.setStroke(dp(1),stroke);return d;}
    GradientDrawable heroBg(){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{DEEP,0xff267650});d.setCornerRadius(dp(24));return d;}
    LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    TextView txt(String s,float size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);v.setFontFeatureSettings("kern");v.setTypeface(android.graphics.Typeface.create(bold?"sans-serif-medium":"sans-serif",0));v.setIncludeFontPadding(false);v.setLineSpacing(dp(2),1);return v;}
    void add(LinearLayout parent,View v){parent.addView(v,new LinearLayout.LayoutParams(-1,-2));}
    void gap(LinearLayout p,int h){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    void line(LinearLayout p){View v=new View(this);v.setBackgroundColor(LINE);p.addView(v,new LinearLayout.LayoutParams(-1,dp(1)));}
    void weight(LinearLayout r,View v,int margin){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(margin),0,dp(margin),0);r.addView(v,p);}
    LinearLayout card(){LinearLayout c=col();c.setPadding(dp(16),dp(16),dp(16),dp(16));c.setBackground(bordered(WHITE,20,LINE));return c;}
    void cardAdd(LinearLayout parent,View c){add(parent,c);gap(parent,11);}
    void section(String title,String sub,Runnable action){LinearLayout r=row();LinearLayout c=col();add(c,txt(title,19,INK,true));if(sub!=null&&!sub.isEmpty()){gap(c,4);add(c,txt(sub,12,MUTED,false));}r.addView(c,new LinearLayout.LayoutParams(0,-2,1));if(action!=null)r.addView(button(t("View all ›","सभी देखें ›"),false,action));add(body,r);gap(body,10);}
    TextView button(String label,boolean primary,Runnable action){TextView v=txt(label,14,primary?WHITE:GREEN,true);v.setGravity(Gravity.CENTER);v.setMinHeight(dp(46));v.setPadding(dp(14),dp(12),dp(14),dp(12));v.setBackground(new RippleDrawable(ColorStateList.valueOf(0x22000000),bg(primary?GREEN:SAGE,13),null));v.setOnClickListener(w->{if(!busy)action.run();});v.setFocusable(true);return v;}
    TextView chip(String label,boolean active,Runnable action){TextView v=txt(label,12,active?WHITE:GREEN,true);v.setPadding(dp(13),dp(10),dp(13),dp(10));v.setGravity(Gravity.CENTER);v.setMinHeight(dp(42));v.setBackground(bordered(active?DEEP:WHITE,22,active?DEEP:LINE));v.setOnClickListener(w->{if(!busy)action.run();});return v;}
    TextView pill(String s,int ink,int fill){TextView v=txt(s,11,ink,true);v.setPadding(dp(9),dp(6),dp(9),dp(6));v.setBackground(bg(fill,20));v.setMaxLines(1);return v;}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
    void hideKeyboard(){View v=getCurrentFocus();if(v!=null)((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(v.getWindowToken(),0);}
    void setRoot(){root=new FrameLayout(this);root.setBackgroundColor(BG);shell=col();root.addView(shell,new FrameLayout.LayoutParams(-1,-1));setContentView(root);}
    void load(){
        busy=true;setRoot();LinearLayout wait=col();wait.setGravity(Gravity.CENTER);wait.setPadding(dp(35),dp(35),dp(35),dp(35));wait.setBackgroundColor(DEEP);
        Icon mark=new Icon("animal",WHITE);wait.addView(mark,new LinearLayout.LayoutParams(dp(72),dp(72)));gap(wait,24);
        add(wait,center(txt("PashuSetu",34,WHITE,true)));gap(wait,8);add(wait,center(txt("पशुसेतु  •  Animal care",15,0xffc4deca,false)));gap(wait,36);
        ProgressBar p=new ProgressBar(this);p.setIndeterminateTintList(ColorStateList.valueOf(0xffd5ecad));wait.addView(p,new LinearLayout.LayoutParams(dp(36),dp(36)));gap(wait,15);add(wait,center(txt("Opening your animal register…",13,WHITE,false)));
        shell.addView(wait,new LinearLayout.LayoutParams(-1,-1));
        io.execute(()->{try{JSONObject loaded=store.read();runOnUiThread(()->{if(isFinishing())return;data=loaded;hi=data.optBoolean("hi");busy=false;render();});}catch(Exception e){runOnUiThread(()->{busy=false;setRoot();LinearLayout c=col();c.setPadding(dp(24),dp(40),dp(24),dp(24));add(shell,c);add(c,txt("Could not open your register",25,INK,true));gap(c,12);add(c,txt("Your saved file was not overwritten. Free some storage or restore a known-good backup.",14,MUTED,false));gap(c,16);add(c,button("Retry",true,this::load));});}});
    }
    TextView center(TextView v){v.setGravity(Gravity.CENTER);return v;}
    void showBusy(String label){busy=true;overlay=new FrameLayout(this);overlay.setBackgroundColor(0x77132e24);overlay.setClickable(true);LinearLayout panel=card();panel.setGravity(Gravity.CENTER);ProgressBar p=new ProgressBar(this);p.setIndeterminateTintList(ColorStateList.valueOf(GREEN));panel.addView(p,new LinearLayout.LayoutParams(dp(34),dp(34)));gap(panel,15);add(panel,center(txt(label,15,INK,true)));FrameLayout.LayoutParams fl=new FrameLayout.LayoutParams(dp(238),-2,Gravity.CENTER);overlay.addView(panel,fl);root.addView(overlay,new FrameLayout.LayoutParams(-1,-1));}
    void endBusy(){busy=false;if(overlay!=null){root.removeView(overlay);overlay=null;}}
    void save(JSONObject next,Runnable done){if(busy)return;hideKeyboard();showBusy(t("Saving records…","रिकॉर्ड सहेज रहे हैं…"));io.execute(()->{try{store.write(RegisterStore.validate(next));runOnUiThread(()->{endBusy();data=next;hi=data.optBoolean("hi");done.run();});}catch(Exception e){runOnUiThread(()->{endBusy();new AlertDialog.Builder(this).setTitle(t("Could not save","सहेज नहीं सके")).setMessage(e.getMessage()==null?"Check available storage.":e.getMessage()).setPositiveButton("OK",null).show();});}});}
    void gotoPage(String s){if(busy)return;hideKeyboard();screen=s;typeFilter="";search="";speciesFilter="All";healthFilter="All";render();}
    void profile(String id){animalId=id;profileTab="Overview";screen="profile";render();}
    void render(){
        if(data==null)return;setRoot();
        LinearLayout top=row();top.setPadding(dp(17),dp(12),dp(17),dp(12));top.setBackgroundColor(WHITE);
        FrameLayout brand=new FrameLayout(this);brand.setBackground(bg(GREEN,13));Icon i=new Icon("animal",WHITE);brand.addView(i,new FrameLayout.LayoutParams(dp(28),dp(28),Gravity.CENTER));top.addView(brand,new LinearLayout.LayoutParams(dp(42),dp(42)));
        LinearLayout title=col();title.setPadding(dp(11),0,0,0);add(title,txt("PashuSetu",21,INK,true));gap(title,3);add(title,txt(t("FIELD EDITION  •  पशुसेतु","ग्राम पशु देखभाल"),10,MUTED,true));top.addView(title,new LinearLayout.LayoutParams(0,-2,1));
        top.addView(chip(t("हिन्दी","English"),false,()->{try{JSONObject next=copy(data);next.put("hi",!hi);save(next,this::render);}catch(Exception e){toast("Unable to change language");}}));
        add(shell,top);line(shell);
        scroll=new ScrollView(this);scroll.setFillViewport(false);scroll.setClipToPadding(false);scroll.setVerticalScrollBarEnabled(false);
        body=col();body.setPadding(dp(17),dp(18),dp(17),dp(23));scroll.addView(body,new ScrollView.LayoutParams(-1,-2));shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        switch(screen){case "animals":animalList();break;case "profile":profilePage();break;case "records":recordsPage();break;case "reports":reportsPage();break;case "settings":settingsPage();break;case "form":formPage();break;default:dashboard();}
        if(!screen.equals("form"))bottom();
    }
    void bottom(){line(shell);nav=row();nav.setPadding(dp(7),dp(6),dp(7),dp(6));nav.setBackgroundColor(WHITE);
        String[] k={"home","animals","records","reports","settings"},en={"Home","Animals","Records","Reports","Settings"},hn={"होम","पशु","रिकॉर्ड","रिपोर्ट","सेटिंग"};
        for(int j=0;j<k.length;j++){final String p=k[j];boolean active=screen.equals(p)||(screen.equals("profile")&&p.equals("animals"));LinearLayout c=col();c.setGravity(Gravity.CENTER);c.setPadding(0,dp(3),0,dp(3));FrameLayout capsule=new FrameLayout(this);capsule.setBackground(bg(active?SAGE:WHITE,15));Icon icon=new Icon(p,active?GREEN:MUTED);capsule.addView(icon,new FrameLayout.LayoutParams(dp(23),dp(23),Gravity.CENTER));c.addView(capsule,new LinearLayout.LayoutParams(dp(48),dp(30)));gap(c,3);add(c,center(txt(t(en[j],hn[j]),10,active?GREEN:MUTED,true)));c.setOnClickListener(v->gotoPage(p));c.setContentDescription(t(en[j],hn[j]));c.setFocusable(true);nav.addView(c,new LinearLayout.LayoutParams(0,dp(58),1));}add(shell,nav);}
    void head(String e,String h,String sub){add(body,txt(t(e,h),28,INK,true));gap(body,5);add(body,txt(sub,13,MUTED,false));gap(body,17);}
    void empty(String title,String detail,Runnable action){LinearLayout c=card();add(c,txt(title,17,INK,true));gap(c,7);add(c,txt(detail,13,MUTED,false));if(action!=null){gap(c,12);add(c,button(t("Add first animal","पहला पशु जोड़ें"),true,action));}cardAdd(body,c);}
    ArrayList<JSONObject> due(){HashMap<String,JSONObject> latest=new HashMap<>();for(JSONObject r:records()){String k=str(r,"type");if(!Arrays.asList("health","vaccine","deworm","breeding").contains(k))continue;String key=str(r,"animal")+"|"+k+"|"+(k.equals("vaccine")?str(r,"title").toLowerCase(Locale.ROOT):"");JSONObject old=latest.get(key);if(old==null||str(old,"date").compareTo(str(r,"date"))<=0)latest.put(key,r);}ArrayList<JSONObject> d=new ArrayList<>();for(JSONObject r:latest.values())if(!str(r,"due").isEmpty())d.add(r);d.sort(Comparator.comparing(r->str(r,"due")));return d;}
    LinearLayout metric(String icon,String value,String label,int color,int fill){LinearLayout c=card();FrameLayout badge=new FrameLayout(this);badge.setBackground(bg(fill,12));badge.addView(new Icon(icon,color),new FrameLayout.LayoutParams(dp(23),dp(23),Gravity.CENTER));c.addView(badge,new LinearLayout.LayoutParams(dp(38),dp(38)));gap(c,10);add(c,txt(value,28,INK,true));gap(c,5);add(c,txt(label,12,MUTED,true));return c;}
    LinearLayout action(String key,String label,Runnable fn){LinearLayout c=col();c.setPadding(dp(10),dp(12),dp(10),dp(12));c.setBackground(new RippleDrawable(ColorStateList.valueOf(0x11000000),bordered(WHITE,16,LINE),null));c.setGravity(Gravity.CENTER);FrameLayout icon=new FrameLayout(this);icon.setBackground(bg(key.equals("health")?0xfff8e9e1:key.equals("production")?SKY:SAGE,13));icon.addView(new Icon(key,key.equals("health")?RUST:GREEN),new FrameLayout.LayoutParams(dp(24),dp(24),Gravity.CENTER));c.addView(icon,new LinearLayout.LayoutParams(dp(39),dp(39)));gap(c,9);TextView l=center(txt(label,11,INK,true));l.setMinHeight(dp(29));add(c,l);c.setOnClickListener(v->{if(!busy)fn.run();});c.setFocusable(true);return c;}
    void quickActions(String id,boolean all){String[] keys=all?TYPES:new String[]{"health","vaccine","production","finance"};int columns=all?3:4;for(int k=0;k<keys.length;k+=columns){LinearLayout r=row();for(int j=k;j<k+columns;j++){if(j<keys.length){String type=keys[j];weight(r,action(type,typeName(type),()->openRecord(type,id,"")),3);}else weight(r,new View(this),3);}add(body,r);gap(body,8);}}
    void dashboard(){
        LinearLayout h=row();LinearLayout lc=col();add(lc,txt(t("YOUR FARM • TODAY","आपका फार्म • आज"),11,MUTED,true));gap(lc,5);add(lc,txt(t("Farm workspace","फार्म कार्यक्षेत्र"),28,INK,true));h.addView(lc,new LinearLayout.LayoutParams(0,-2,1));h.addView(pill(t("Offline","ऑफलाइन"),GREEN,SAGE));add(body,h);gap(body,16);
        LinearLayout hero=col();hero.setBackground(heroBg());hero.setPadding(dp(21),dp(22),dp(21),dp(21));LinearLayout r=row();LinearLayout text=col();add(text,txt(t("ANIMAL CARE REGISTER","पशु देखभाल रजिस्टर"),10,0xffbddeca,true));gap(text,10);add(text,txt(t("Every animal.\nEvery day.","हर पशु।\nहर दिन।"),30,WHITE,true));gap(text,9);add(text,txt(t("Health, growth and care in one place.","स्वास्थ्य और वृद्धि एक जगह।"),13,0xffd5e8dc,false));r.addView(text,new LinearLayout.LayoutParams(0,-2,1));Icon cow=new Icon("animal",0xffc3e3ca);r.addView(cow,new LinearLayout.LayoutParams(dp(86),dp(86)));add(hero,r);gap(hero,18);TextView ab=button(t("+  Register animal","+  पशु जोड़ें"),false,()->openAnimal(""));ab.setBackground(bg(0xffdcefc5,13));add(hero,ab);cardAdd(body,hero);
        int healthy=0,sick=0,preg=0,b=0;for(JSONObject a:animals()){switch(str(a,"status")){case "Healthy":healthy++;break;case "Sick":sick++;break;}if(str(a,"pregnancy").equals("Pregnant"))preg++;}for(JSONObject x:due())if(str(x,"due").compareTo(today())<=0)b++;
        section(t("Herd at a glance","पशुओं का सारांश"),"",null);LinearLayout m=row();weight(m,metric("animal",""+animals().size(),t("Total animals","कुल पशु"),GREEN,SAGE),3);weight(m,metric("check",""+healthy,t("Healthy","स्वस्थ"),GREEN,SAGE),3);add(body,m);gap(body,7);m=row();weight(m,metric("health",""+sick,t("Need attention","बीमार"),RUST,0xfffbe9e2),3);weight(m,metric("calendar",""+b,t("Due reminders","बकाया जांच"),0xff996621,0xffffefd4),3);add(body,m);gap(body,18);
        section(t("Quick actions","त्वरित कार्य"),"",null);quickActions("",false);gap(body,15);
        section(t("Care schedule","देखभाल की तारीखें"),t("Upcoming and overdue","आगामी और बकाया"),null);if(due().isEmpty())empty(t("You're all clear","कोई बकाया नहीं"),t("Record checkups or vaccination next dates here.","अगली जांच या टीके की तारीख दर्ज करें।"),null);else{int count=0;for(JSONObject x:due()){if(count++>=4)break;reminderCard(x);}}
        gap(body,10);section(t("Your animals","आपके पशु"),"",()->gotoPage("animals"));if(animals().isEmpty()){empty(t("Start your register","पहला पशु जोड़ें"),t("Register the ear tag, breed and health status. You can add more details later.","टैग, नस्ल और स्वास्थ्य दर्ज करें।"),()->openAnimal(""));add(body,button(t("Explore sample data","नमूना डेटा देखें"),false,this::demo));}else{int count=0;for(JSONObject a:animals()){if(count++>=4)break;animalCard(a,body);}}
        gap(body,15);section(t("Herd health","पशु स्वास्थ्य"),"",()->gotoPage("reports"));LinearLayout c=card();drawDonut(c,STATUS,new double[]{healthy,sick,animals().stream().filter(a->str(a,"status").equals("Recovering")).count(),animals().stream().filter(a->str(a,"status").equals("Unknown")).count()},new int[]{GREEN,RUST,GOLD,0xff9aafa5},true);cardAdd(body,c);
    }
    void reminderCard(JSONObject x){LinearLayout c=card(),r=row();Icon i=new Icon("calendar",GREEN);r.addView(i,new LinearLayout.LayoutParams(dp(34),dp(34)));LinearLayout text=col();text.setPadding(dp(9),0,dp(8),0);add(text,txt(val(x,"title").equals("—")?typeName(str(x,"type")):val(x,"title"),15,INK,true));gap(text,5);add(text,txt(val(animal(str(x,"animal")),"name")+" • "+str(x,"due"),12,MUTED,false));r.addView(text,new LinearLayout.LayoutParams(0,-2,1));boolean late=str(x,"due").compareTo(today())<=0;r.addView(pill(late?t("Due","बकाया"):t("Scheduled","आगामी"),late?RUST:GREEN,late?0xfffce9df:SAGE));add(c,r);c.setOnClickListener(v->profile(str(x,"animal")));cardAdd(body,c);}
    void animalCard(JSONObject a,LinearLayout target){LinearLayout c=card(),r=row();FrameLayout symbol=new FrameLayout(this);symbol.setBackground(bg(SAGE,15));symbol.addView(new Icon("animal",GREEN),new FrameLayout.LayoutParams(dp(31),dp(31),Gravity.CENTER));r.addView(symbol,new LinearLayout.LayoutParams(dp(49),dp(49)));LinearLayout text=col();text.setPadding(dp(12),0,dp(5),0);add(text,txt(val(a,"name"),16,INK,true));gap(text,5);add(text,txt(speciesName(str(a,"species"))+" • "+(str(a,"tag").isEmpty()?val(a,"breed"):val(a,"tag")),12,MUTED,false));r.addView(text,new LinearLayout.LayoutParams(0,-2,1));boolean sick=str(a,"status").equals("Sick");r.addView(pill(statusName(str(a,"status")),sick?RUST:GREEN,sick?0xfffce9e1:SAGE));gap(c,1);add(c,r);c.setOnClickListener(v->profile(str(a,"id")));c.setFocusable(true);cardAdd(target,c);}
