    void bar(LinearLayout c,String label,double v,double max,int color){LinearLayout r=row();r.addView(txt(label,13,MUTED,true),new LinearLayout.LayoutParams(0,-2,1));r.addView(txt(cash(v),13,INK,true));add(c,r);gap(c,6);FrameLayout track=new FrameLayout(this);track.setBackground(bg(0xffedf1eb,6));View fill=new View(this);fill.setBackground(bg(color,6));track.addView(fill,new FrameLayout.LayoutParams(0,-1));track.post(()->{ViewGroup.LayoutParams p=fill.getLayoutParams();p.width=(int)(track.getWidth()*(max==0?0:v/max));fill.setLayoutParams(p);});c.addView(track,new LinearLayout.LayoutParams(-1,dp(10)));gap(c,13);}
    static class Field {String key,en,hn,kind;String[] options;boolean req;Field(String k,String e,String h,String type,boolean r,String... o){key=k;en=e;hn=h;kind=type;req=r;options=o;}}
