    Field[] animalFields(){return new Field[]{f("name","Animal name","पशु नाम","text",true),f("species","Species","पशु प्रकार","choice",true,SPECIES),f("breed","Breed","नस्ल","text",false),f("tag","Ear tag / ID","कान का टैग","text",false),f("sex","Sex","लिंग","choice",false,"Unknown","Female","Male"),f("dob","Date of birth","जन्म तिथि","date",false),f("age","Estimated age (months)","उम्र (महीने)","num",false),f("weight","Weight (kg)","वजन (किलो)","num",false),f("color","Colour / markings","रंग / पहचान","text",false),f("status","Health status","स्वास्थ्य","choice",true,"Unknown","Healthy","Sick","Recovering"),f("pregnancy","Pregnancy","गर्भावस्था","choice",false,"Unknown","Not applicable","Not pregnant","Pregnant"),f("owner","Owner name","मालिक का नाम","text",false),f("phone","Mobile number","मोबाइल नंबर","phone",false),f("village","Village","गांव","text",false),f("address","Address","पता","multi",false),f("purchase","Purchase date","खरीद तिथि","date",false),f("cost","Purchase cost (₹)","खरीद खर्च","num",false),f("notes","Other notes","अन्य जानकारी","multi",false)};}
    Field[] recordFields(String k){ArrayList<Field> l=new ArrayList<>();switch(k){
        case "health":l.add(f("title","Reason / diagnosis","कारण / निदान","text",true));l.add(f("symptoms","Symptoms","लक्षण","multi",false));l.add(f("treatment","Treatment provided","उपचार","multi",false));l.add(f("medicine","Vet-prescribed medicine and dose","डॉक्टर की दवा और मात्रा","multi",false));l.add(f("temperature","Temperature (°C)","तापमान","num",false));l.add(f("vet","Veterinarian","पशु चिकित्सक","text",false));l.add(f("due","Follow-up date","अगली जांच","date",false));l.add(f("condition","Condition after visit","जांच के बाद स्थिति","choice",false,"Unchanged","Healthy","Sick","Recovering"));break;
        case "vaccine":case "deworm":l.add(f("title",k.equals("vaccine")?"Vaccine name":"Deworming medicine",k.equals("vaccine")?"टीका":"कृमिनाशक दवा","text",true));l.add(f("batch","Batch number","बैच नंबर","text",false));l.add(f("medicine","Dose given by vet","डॉक्टर की मात्रा","text",false));l.add(f("vet","Veterinarian","पशु चिकित्सक","text",false));l.add(f("due","Next due (vet advised)","अगली तारीख","date",false));break;
        case "breeding":l.add(f("title","Event description","घटना","text",true));l.add(f("event","Event type","प्रकार","choice",false,"Heat","Insemination","Pregnancy check","Birth","Other"));l.add(f("due","Expected birth / follow-up","संभावित प्रसव / जांच","date",false));l.add(f("offspring","Offspring details","बच्चों की जानकारी","multi",false));l.add(f("vet","Veterinarian","पशु चिकित्सक","text",false));break;
        case "production":l.add(f("milk","Milk (litres)","दूध (लीटर)","num",false));l.add(f("weight","Body weight (kg)","वजन (किलो)","num",false));l.add(f("eggs","Eggs (count)","अंडे","num",false));break;
        case "feed":l.add(f("title","Feed type","चारा","text",true));l.add(f("quantity","Quantity (kg)","मात्रा (किलो)","num",false));l.add(f("schedule","Feeding schedule","खिलाने का समय","text",false));l.add(f("cost","Feed cost (₹)","खर्च","num",false));break;
        case "finance":l.add(f("title","Description","विवरण","text",true));l.add(f("direction","Transaction type","लेनदेन","choice",true,"Income","Expense"));l.add(f("amount","Amount (₹)","राशि","num",true));break;
    }l.add(f("notes","Notes","टिप्पणी","multi",false));return l.toArray(new Field[0]);}
